let item = {};
try {
  item = $input.first().json || {};
} catch (e) {
  try { item = $json || {}; } catch (e2) {}
}

let usdAmount = parseFloat(item.monto_usd || item.usd || 0);
let months = parseInt(item.meses || item.mes || 0);

const query = (item.query || '').toString().toLowerCase();
if (!months && query) {
  if (query.includes('12') || query.includes('año') || query.includes('ano') || query.includes('84')) {
    months = 12;
  } else if (query.includes('6') || query.includes('48')) {
    months = 6;
  } else if (query.includes('3') || query.includes('24')) {
    months = 3;
  } else if (query.includes('1') || query.includes('8')) {
    months = 1;
  }
}

if (!usdAmount && months) {
  if (months === 1) usdAmount = 8;
  else if (months === 3) usdAmount = 24;
  else if (months === 6) usdAmount = 48;
  else if (months === 12) usdAmount = 84;
}

if (!usdAmount) {
  usdAmount = 8;
}

let binanceRate = 0;

// 1. Fetch live Binance P2P rate via this.helpers.httpRequest
try {
  const bRes = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://p2p.binance.com/bapi/c2c/v2/friendly/c2c/adv/search',
    headers: {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
      'Content-Type': 'application/json'
    },
    body: {
      asset: 'USDT',
      fiat: 'VES',
      merchantCheck: false,
      page: 1,
      payTypes: ['PagoMovil'],
      publisherType: null,
      rows: 10,
      tradeType: 'BUY'
    },
    json: true
  });
  const ads = bRes?.data || [];
  const validPrices = ads
    .map(a => parseFloat(a.adv?.price || 0))
    .filter(p => p > 800);
  if (validPrices.length > 0) {
    binanceRate = validPrices[0];
  }
} catch (e) {}

// 2. Fallback: DolarAPI Paralelo
let paraleloRate = 0;
if (!binanceRate) {
  try {
    const pRes = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://ve.dolarapi.com/v1/dolares/paralelo',
      headers: { 'User-Agent': 'Mozilla/5.0' },
      json: true
    });
    paraleloRate = parseFloat(pRes?.promedio || 0);
  } catch (e) {}
}

// 3. Fallback: DolarAPI Oficial
let oficialRate = 0;
if (!binanceRate && !paraleloRate) {
  try {
    const oRes = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://ve.dolarapi.com/v1/dolares/oficial',
      headers: { 'User-Agent': 'Mozilla/5.0' },
      json: true
    });
    oficialRate = parseFloat(oRes?.promedio || 0);
  } catch (e) {}
}

const effectiveRate = binanceRate || paraleloRate || oficialRate || 963.00;
const totalBs = (usdAmount * effectiveRate).toFixed(2);

return [{
  json: {
    tasa_del_dia: effectiveRate.toFixed(2),
    monto_usd: usdAmount,
    meses: months || 1,
    total_bs: totalBs,
    fuente_tasa: binanceRate ? 'Binance P2P Pago Móvil' : (paraleloRate ? 'DolarAPI Paralelo' : 'Tasa Base'),
    banco: 'Bancamiga',
    telefono: '04246861135',
    rif: 'J405259221',
    beneficiario: 'ArialStore C.A.',
    qr_url: 'https://raw.githubusercontent.com/totaltvusa/images/main/Arialstorepm.jpeg',
    resumen_precios_bs: {
      plan_1_mes: (8 * effectiveRate).toFixed(2) + ' Bs ($8)',
      plan_3_meses: (24 * effectiveRate).toFixed(2) + ' Bs ($24)',
      plan_6_meses: (48 * effectiveRate).toFixed(2) + ' Bs ($48)',
      plan_12_meses: (84 * effectiveRate).toFixed(2) + ' Bs ($84)'
    }
  }
}];
